preConditionHook:
// Brooks's magnets -- yesterday's high, low, open and close -- as one rule with
// a selector: 0 = high, 1 = low, 2 = open, 3 = close.
//
// ONE BAR IS ONE SESSION. On a daily or 1440-minute series the prior session's
// four reference prices are high[1] / low[1] / open[1] / close[1], so the rule
// needs no session model, no HighD/LowD/OpenD/CloseD and no -1 warm-up
// sentinel. On a finer intraday series this reads the prior BAR, which is not
// what Brooks means -- daily or 1440-minute bars only.
//
// A TOUCH, not a break: the bar's low (long, testing the level from below) or
// high (short, from above) comes within tol of the level. CloseAbovePriorHigh
// is the break by the close, a different test.
//
// The selector's comparisons mirror the twin's EL if/else-if chain on
// levelSelect, so they go through el_le even though levelSelect only ever
// holds an exact optimizer value and the 2.22e-12 tolerance cannot change
// which branch is taken.
if (el_le(levelSelect, 0)) {
    level = high[1];
} else if (el_le(levelSelect, 1)) {
    level = low[1];
} else if (el_le(levelSelect, 2)) {
    level = open[1];
} else {
    level = close[1];
}
// Tolerance in ATR, not in ticks: the sources say "1 or 2 ticks", but MinMove
// and PriceScale are UNKNOWN in EL_FEATURES and the engine exposes no tick
// size to a strategy at all, so the margin is a fraction of the N-bar ATR --
// the substitution PullbackFromRecentHigh and DistanceAboveRecentLow make.
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and thereafter
// updated as TWO statements -- EL evaluates S[1] + in - out left to right, and folding it
// to S += in - out rounds differently (@OJ 2015-02-20). One call site, in the
// hook, so it advances exactly once per bar.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
tol = toleranceAtr * atr;
